"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[8973],{39886:e=>{e.exports=JSON.parse('{"functions":[{"name":"lerp","desc":"Interpolates between two numbers.\\n\\n#### Example:\\n```lua\\nMathUtil.lerp(0, 10, .5) -- 5\\nMathUtil.lerp(0, 10, 1) -- 10\\n```","params":[{"name":"start","desc":"","lua_type":"number"},{"name":"stop","desc":"","lua_type":"number"},{"name":"alpha","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"number"}],"function_type":"static","source":{"line":26,"path":"src/MathUtil.luau"}},{"name":"round","desc":"Rounds a number to the nearest integer.\\n\\n#### Example:\\n```lua\\nMathUtil.round(1.5) -- 2\\nMathUtil.round(1.4) -- 1\\n```","params":[{"name":"_number","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"number"}],"function_type":"static","source":{"line":43,"path":"src/MathUtil.luau"}},{"name":"formatInt","desc":"Formats a number to have commas.\\n\\n#### Example:\\n```lua\\nMathUtil.formatInt(1000) -- 1,000\\nMathUtil.formatInt(1000.01) -- 1,000.01\\n```","params":[{"name":"number","desc":"","lua_type":"number"},{"name":"decimals","desc":"The number of decimal places to round to. Defaults to 2.","lua_type":"number?"}],"returns":[{"desc":"","lua_type":"string"}],"function_type":"static","source":{"line":65,"path":"src/MathUtil.luau"}},{"name":"random","desc":"Returns a random integer between two numbers (inclusive), or a float when `float`\\nis true.\\n\\n#### Example:\\n```lua\\nMathUtil.random(1, 10) -- 5\\nMathUtil.random(1, 10, true) -- 5.5\\nMathUtil.random(10) -- 5 (min defaults to 1)\\n```","params":[{"name":"minValue","desc":"The minimum, or the maximum when `maxValue` is nil.","lua_type":"number"},{"name":"maxValue","desc":"","lua_type":"number?"},{"name":"float","desc":"Whether to return as a float or not. Defaults to false.","lua_type":"boolean?"}],"returns":[{"desc":"","lua_type":"number"}],"function_type":"static","source":{"line":109,"path":"src/MathUtil.luau"}},{"name":"randomRange","desc":"Returns a random float between `minValue` and `maxValue`, using a shared Random\\nobject.","params":[{"name":"minValue","desc":"","lua_type":"number"},{"name":"maxValue","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"number"}],"function_type":"static","source":{"line":132,"path":"src/MathUtil.luau"}},{"name":"randomString","desc":"Returns a random string of letters and digits.\\n\\n#### Example:\\n```lua\\nMathUtil.randomString() -- \\"aB3dE9gH1jK0mN4pQr\\"\\nMathUtil.randomString(10) -- \\"aB3dE9gH1j\\"\\n```","params":[{"name":"length","desc":"The length of the string. Defaults to 18.","lua_type":"number?"}],"returns":[{"desc":"","lua_type":"string"}],"function_type":"static","source":{"line":152,"path":"src/MathUtil.luau"}},{"name":"randomObj","desc":"Returns a random element of an array, or a random child of an Instance.\\n\\n#### Example:\\n```lua\\nMathUtil.randomObj({ \\"a\\", \\"b\\", \\"c\\" }) -- \\"b\\"\\nMathUtil.randomObj(workspace.Map.SpawnPoints) -- SpawnPoint3\\n```","params":[{"name":"obj","desc":"","lua_type":"{ any } | Instance"}],"returns":[{"desc":"","lua_type":"any"}],"function_type":"static","source":{"line":178,"path":"src/MathUtil.luau"}},{"name":"shortenNumber","desc":"Shortens a large number to a readable format.\\nUseful for displaying large numbers that don\'t require exact precision.\\nCommon use cases are for displaying XP, money in leaderboards, damage etc.\\n\\nShortened numbers keep one decimal place, truncated rather than rounded, so a value never\\nreads as more than it is: 999,999 shortens to 999.9K instead of rolling up to 1,000K.\\n\\n#### Example:\\n```lua\\nMathUtil.shortenNumber(1000) -- 1K\\nMathUtil.shortenNumber(1200) -- 1.2K\\nMathUtil.shortenNumber(999999) -- 999.9K\\nMathUtil.shortenNumber(1000000) -- 1M\\nMathUtil.shortenNumber(1000000000) -- 1B\\nMathUtil.shortenNumber(1000000000000) -- 1T\\nMathUtil.shortenNumber(1000000000000000) -- 1Q\\n```\\n\\nminimumTiers is useful for when you want to shorten a number but only if it\'s at least a certain tier.\\nFor example, to only shorten numbers of 1,000,000 or more:\\n```lua\\nMathUtil.shortenNumber(250000, 2) -- 250,000\\nMathUtil.shortenNumber(1000000, 2) -- 1M\\n```\\n\\nA tier is the amount of commas in a number. For example, 1,000,000 has 2 tiers and 1,000 has 1 tier.\\n\\nTier list and their abbreviations:\\n- 1,000 = K\\n- 1,000,000 = M\\n- 1,000,000,000 = B\\n- 1,000,000,000,000 = T\\n- 1,000,000,000,000,000 = Q","params":[{"name":"number","desc":"","lua_type":"number | string"},{"name":"minimumTiers","desc":"The minimum number of tiers to shorten. Defaults to 1.","lua_type":"number?"}],"returns":[{"desc":"","lua_type":"string"}],"function_type":"static","source":{"line":235,"path":"src/MathUtil.luau"}},{"name":"getVector3","desc":"Gets a Vector3 from an object containing a Vector3 or CFrame.\\n\\n#### Supports:\\n- Vector3\\n- CFrame\\n- Attachment\\n- BasePart\\n- CFrameValue\\n- Vector3Value\\n- Camera","params":[{"name":"object","desc":"","lua_type":"Vector3 | CFrame | Instance"}],"returns":[{"desc":"","lua_type":"Vector3?"}],"function_type":"static","source":{"line":283,"path":"src/MathUtil.luau"}},{"name":"getDistance","desc":"Gets the distance between two positions. Accepts anything [MathUtil.getVector3]\\nsupports, and errors if either value has no position.","params":[{"name":"origin","desc":"","lua_type":"Vector3 | CFrame | Instance"},{"name":"target","desc":"","lua_type":"Vector3 | CFrame | Instance"}],"returns":[{"desc":"","lua_type":"number"}],"function_type":"static","source":{"line":305,"path":"src/MathUtil.luau"}},{"name":"getPartBottomSurface","desc":"Returns the CFrame at the centre of a part\'s bottom face, keeping the part\'s\\nrotation.","params":[{"name":"part","desc":"","lua_type":"BasePart"}],"returns":[{"desc":"","lua_type":"CFrame"}],"function_type":"static","source":{"line":329,"path":"src/MathUtil.luau"}},{"name":"randomInDisc","desc":"Returns a random flat offset (Y = 0) inside a disc of the given radius. Points are\\nspread evenly over the disc\'s area rather than bunched at its centre.\\n\\n```lua\\nlocal spawnPosition = center + MathUtil.randomInDisc(20)\\n```","params":[{"name":"radius","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"Vector3"}],"function_type":"static","source":{"line":345,"path":"src/MathUtil.luau"}},{"name":"getRandomInPart","desc":"Returns a random CFrame across the part\'s X and Z extents, at the height of the\\npart\'s centre and with the part\'s rotation.","params":[{"name":"part","desc":"","lua_type":"BasePart"}],"returns":[{"desc":"","lua_type":"CFrame"}],"function_type":"static","source":{"line":360,"path":"src/MathUtil.luau"}},{"name":"roundNumber","desc":"Rounds `num` to the nearest value with `numPlaces` decimal places.\\n\\n```lua\\nMathUtil.roundNumber(1.236, 2) -- 1.24\\nMathUtil.roundNumber(1.231, 2) -- 1.23\\n```","params":[{"name":"num","desc":"","lua_type":"number"},{"name":"numPlaces","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"number"}],"function_type":"static","source":{"line":384,"path":"src/MathUtil.luau"}},{"name":"isNumberSecure","desc":"Returns true only when `number` is a number and not negative. Useful for\\nvalidating amounts sent by clients.\\n\\n```lua\\nMathUtil.isNumberSecure(5) -- true\\nMathUtil.isNumberSecure(-5) -- false\\nMathUtil.isNumberSecure(\\"5\\") -- false\\n```","params":[{"name":"number","desc":"","lua_type":"any"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":403,"path":"src/MathUtil.luau"}}],"properties":[],"types":[],"name":"MathUtil","desc":"Number helpers: interpolation, rounding, formatting and abbreviating numbers,\\nrandom values, and positions on parts.","source":{"line":8,"path":"src/MathUtil.luau"}}')}}]);